ALTER TABLE tenants ADD COLUMN reviews_enabled INTEGER NOT NULL DEFAULT 1;
ALTER TABLE tenants ADD COLUMN rebooking_days INTEGER NOT NULL DEFAULT 0 CHECK(rebooking_days BETWEEN 0 AND 180);
CREATE TABLE payment_records(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,booking_id TEXT NOT NULL,customer_id TEXT NOT NULL,amount_centimes INTEGER NOT NULL CHECK(amount_centimes BETWEEN 0 AND 10000000),eligible_centimes INTEGER NOT NULL CHECK(eligible_centimes BETWEEN 0 AND amount_centimes),redeemed_centimes INTEGER NOT NULL CHECK(redeemed_centimes BETWEEN 0 AND 10000000 AND amount_centimes+redeemed_centimes>0),earned_centimes INTEGER NOT NULL CHECK(earned_centimes>=0),rate_bps INTEGER NOT NULL CHECK(rate_bps IN (0,100,200)),expiry_days INTEGER NOT NULL,verification TEXT NOT NULL DEFAULT 'merchant_reported' CHECK(verification='merchant_reported'),authorization TEXT NOT NULL CHECK(authorization IN ('none','in_person_verified')),actor TEXT NOT NULL,receipt_reference TEXT,tenant_revision INTEGER NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TABLE refund_records(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,payment_id TEXT NOT NULL,cash_centimes INTEGER NOT NULL CHECK(cash_centimes>=0),credit_centimes INTEGER NOT NULL CHECK(credit_centimes>=0 AND cash_centimes+credit_centimes>0),reason TEXT NOT NULL,actor TEXT NOT NULL,idempotency_key TEXT NOT NULL,request_hash TEXT NOT NULL,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,idempotency_key),FOREIGN KEY(tenant_id,payment_id) REFERENCES payment_records(tenant_id,id));
CREATE TABLE loyalty_ledger(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,payment_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('earn','redeem','reversal','restore','expire')),amount_centimes INTEGER NOT NULL,reference_id TEXT,event_key TEXT NOT NULL,expires_at INTEGER,created_at INTEGER NOT NULL,UNIQUE(tenant_id,id),UNIQUE(tenant_id,event_key),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),FOREIGN KEY(tenant_id,payment_id) REFERENCES payment_records(tenant_id,id),FOREIGN KEY(tenant_id,reference_id) REFERENCES loyalty_ledger(tenant_id,id));
CREATE TABLE loyalty_allocations(tenant_id TEXT NOT NULL,debit_id TEXT NOT NULL,grant_id TEXT NOT NULL,amount_centimes INTEGER NOT NULL CHECK(amount_centimes>0),PRIMARY KEY(tenant_id,debit_id,grant_id),FOREIGN KEY(tenant_id,debit_id) REFERENCES loyalty_ledger(tenant_id,id),FOREIGN KEY(tenant_id,grant_id) REFERENCES loyalty_ledger(tenant_id,id));
CREATE VIEW loyalty_lots AS SELECT l.*,l.amount_centimes-COALESCE((SELECT SUM(a.amount_centimes) FROM loyalty_allocations a WHERE a.tenant_id=l.tenant_id AND a.grant_id=l.id),0)+COALESCE((SELECT SUM(d.amount_centimes) FROM loyalty_ledger d WHERE d.tenant_id=l.tenant_id AND d.reference_id=l.id),0) remaining FROM loyalty_ledger l WHERE l.kind IN ('earn','restore');
CREATE VIEW loyalty_balances AS SELECT tenant_id,customer_id,SUM(amount_centimes) balance_centimes FROM loyalty_ledger GROUP BY tenant_id,customer_id;
CREATE TRIGGER payment_guard BEFORE INSERT ON payment_records BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM bookings b JOIN tenants t ON t.id=b.tenant_id WHERE b.tenant_id=NEW.tenant_id AND b.id=NEW.booking_id AND b.customer_id=NEW.customer_id AND b.status='completed' AND t.revision=NEW.tenant_revision AND NEW.rate_bps=t.loyalty_bps AND NEW.expiry_days=t.loyalty_expiry_days AND NEW.earned_centimes=MIN(NEW.eligible_centimes*t.loyalty_bps/10000,t.loyalty_cap)) THEN RAISE(ABORT,'invalid_payment') END; SELECT CASE WHEN NEW.amount_centimes+NEW.redeemed_centimes+COALESCE((SELECT SUM(amount_centimes+redeemed_centimes) FROM payment_records WHERE tenant_id=NEW.tenant_id AND booking_id=NEW.booking_id),0)-COALESCE((SELECT SUM(r.cash_centimes+r.credit_centimes) FROM refund_records r JOIN payment_records p ON p.tenant_id=r.tenant_id AND p.id=r.payment_id WHERE p.tenant_id=NEW.tenant_id AND p.booking_id=NEW.booking_id),0)>(SELECT price_centimes FROM bookings WHERE tenant_id=NEW.tenant_id AND id=NEW.booking_id) THEN RAISE(ABORT,'payment_exceeds_invoice') END; SELECT CASE WHEN NEW.redeemed_centimes>0 AND (NEW.authorization!='in_person_verified' OR NEW.redeemed_centimes<(SELECT loyalty_min_redeem FROM tenants WHERE id=NEW.tenant_id) OR NEW.redeemed_centimes>COALESCE((SELECT balance_centimes FROM loyalty_balances WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id),0) OR NEW.redeemed_centimes>COALESCE((SELECT SUM(MAX(0,remaining)) FROM loyalty_lots WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id AND (expires_at IS NULL OR expires_at>NEW.created_at)),0)) THEN RAISE(ABORT,'insufficient_credit_or_authority') END; END;
CREATE TRIGGER payment_ledger AFTER INSERT ON payment_records BEGIN INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,created_at) SELECT 'redeem:'||NEW.id,NEW.tenant_id,NEW.customer_id,NEW.id,'redeem',-NEW.redeemed_centimes,'redeem:'||NEW.id,NEW.created_at WHERE NEW.redeemed_centimes>0; INSERT INTO loyalty_allocations SELECT NEW.tenant_id,'redeem:'||NEW.id,id,MIN(remaining,NEW.redeemed_centimes-previous) FROM (SELECT id,remaining,COALESCE(SUM(remaining) OVER (ORDER BY created_at,id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) previous FROM loyalty_lots WHERE tenant_id=NEW.tenant_id AND customer_id=NEW.customer_id AND remaining>0 AND (expires_at IS NULL OR expires_at>NEW.created_at)) WHERE previous<NEW.redeemed_centimes; INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,expires_at,created_at) SELECT 'earn:'||NEW.id,NEW.tenant_id,NEW.customer_id,NEW.id,'earn',NEW.earned_centimes,'earn:'||NEW.id,CASE WHEN NEW.expiry_days>0 THEN NEW.created_at+NEW.expiry_days*86400000 ELSE NULL END,NEW.created_at WHERE NEW.earned_centimes>0; END;
CREATE TRIGGER refund_guard BEFORE INSERT ON refund_records BEGIN SELECT CASE WHEN NEW.cash_centimes+COALESCE((SELECT SUM(cash_centimes) FROM refund_records WHERE tenant_id=NEW.tenant_id AND payment_id=NEW.payment_id),0)>(SELECT amount_centimes FROM payment_records WHERE tenant_id=NEW.tenant_id AND id=NEW.payment_id) OR NEW.credit_centimes+COALESCE((SELECT SUM(credit_centimes) FROM refund_records WHERE tenant_id=NEW.tenant_id AND payment_id=NEW.payment_id),0)>(SELECT redeemed_centimes FROM payment_records WHERE tenant_id=NEW.tenant_id AND id=NEW.payment_id) THEN RAISE(ABORT,'refund_exceeds_payment') END; END;
CREATE TRIGGER refund_ledger AFTER INSERT ON refund_records BEGIN INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,reference_id,event_key,created_at) SELECT 'reversal:'||NEW.id,NEW.tenant_id,p.customer_id,p.id,'reversal',-MAX(0,p.earned_centimes-((p.amount_centimes-(SELECT SUM(cash_centimes) FROM refund_records WHERE tenant_id=p.tenant_id AND payment_id=p.id))*p.earned_centimes/MAX(1,p.amount_centimes))+COALESCE((SELECT SUM(amount_centimes) FROM loyalty_ledger WHERE tenant_id=p.tenant_id AND reference_id='earn:'||p.id),0)),'earn:'||p.id,'reversal:'||NEW.id,NEW.created_at FROM payment_records p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.payment_id AND p.earned_centimes>0; INSERT INTO loyalty_ledger(id,tenant_id,customer_id,payment_id,kind,amount_centimes,event_key,expires_at,created_at) SELECT 'restore:'||NEW.id,NEW.tenant_id,p.customer_id,p.id,'restore',NEW.credit_centimes,'restore:'||NEW.id,CASE WHEN p.expiry_days>0 THEN NEW.created_at+p.expiry_days*86400000 ELSE NULL END,NEW.created_at FROM payment_records p WHERE p.tenant_id=NEW.tenant_id AND p.id=NEW.payment_id AND NEW.credit_centimes>0; END;
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON loyalty_ledger BEGIN SELECT RAISE(ABORT,'append_only_ledger'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON loyalty_ledger BEGIN SELECT RAISE(ABORT,'append_only_ledger'); END;
CREATE TRIGGER allocations_no_update BEFORE UPDATE ON loyalty_allocations BEGIN SELECT RAISE(ABORT,'append_only_allocation'); END;
CREATE TRIGGER allocations_no_delete BEFORE DELETE ON loyalty_allocations BEGIN SELECT RAISE(ABORT,'append_only_allocation'); END;
CREATE TRIGGER payments_no_update BEFORE UPDATE ON payment_records BEGIN SELECT RAISE(ABORT,'append_only_payment'); END;
CREATE TRIGGER payments_no_delete BEFORE DELETE ON payment_records BEGIN SELECT RAISE(ABORT,'append_only_payment'); END;
CREATE TRIGGER refunds_no_update BEFORE UPDATE ON refund_records BEGIN SELECT RAISE(ABORT,'append_only_refund'); END;
CREATE TRIGGER refunds_no_delete BEFORE DELETE ON refund_records BEGIN SELECT RAISE(ABORT,'append_only_refund'); END;
CREATE TABLE reviews_prompt_events(tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,booking_id TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(tenant_id,customer_id),FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id),FOREIGN KEY(tenant_id,booking_id) REFERENCES bookings(tenant_id,id));
CREATE INDEX ledger_customer ON loyalty_ledger(tenant_id,customer_id,created_at);
CREATE INDEX payments_booking ON payment_records(tenant_id,booking_id);
